// Keep off the seam:
// @JvmInline value class UserId(...)        -> mangled names in Java
// suspend fun load(): User                  -> Continuation in Java
// sealed class Result                       -> no exhaustiveness for Java
// fun <reified T> json(): T                 -> not callable from Java

// Without target — lands on the CONSTRUCTOR PARAMETER
class User(@Json("user_id") val id: String)
// Moshi reflective reads FIELDS -> no Json found -> key falls back to "id"

// Explicit field target — what Moshi/Gson reflective expects
class User(@field:Json("user_id") val id: String)

// Other targets and the grouped form
class C(
    @get:Json("v") val v: Int,
    @field:[SerialName("x") Transient] val x: Int,
    val d: Int by @delegate:SoftRef("d") SoftRef(0)
)

